def qdrant_store(workspace_id, collection_id, points, **_extra):
    import json, os, datetime, re, uuid, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0013000" if __import__("os").path.isdir("./environment_mix/0013000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        return "qdr_req_" + uuid.uuid4().hex[:24]

    def _finalize(search_requests, req_row, status, result_count=None, err_code=None, err_msg=None):
        req_row["status"] = status
        req_row["updated_at"] = now
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        if result_count is not None:
            req_row["result_count"] = int(result_count)
        if err_code is not None:
            req_row["error_code"] = err_code
        if err_msg is not None:
            req_row["error_message"] = err_msg
        _save("search_requests.json", search_requests)

    # ---- Validate inputs (schema) ----
    if not isinstance(workspace_id, str) or not re.match(r"^qdr_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(collection_id, str) or not re.match(r"^qdr_col_[A-Za-z0-9]+$", collection_id):
        return _err("VALIDATION_ERROR", "Invalid collection_id.")
    if not isinstance(points, list) or len(points) < 1:
        return _err("VALIDATION_ERROR", "points must be a non-empty array.")
    for i, p in enumerate(points):
        if not isinstance(p, dict):
            return _err("VALIDATION_ERROR", f"points[{i}] must be an object.")
        allowed = {"id", "external_point_id", "content_text", "embedding", "payload"}
        extra = set(p.keys()) - allowed
        if extra:
            return _err("VALIDATION_ERROR", f"points[{i}] contains unknown fields: {sorted(extra)}.")
        if "content_text" not in p or "embedding" not in p:
            return _err("VALIDATION_ERROR", f"points[{i}] must include content_text and embedding.")
        if p.get("id") is not None and (not isinstance(p.get("id"), str) or not re.match(r"^qdr_pt_[A-Za-z0-9]+$", p.get("id"))):
            return _err("VALIDATION_ERROR", f"points[{i}].id must match ^qdr_pt_[A-Za-z0-9]+$.")
        if p.get("external_point_id") is not None and not isinstance(p.get("external_point_id"), str):
            return _err("VALIDATION_ERROR", f"points[{i}].external_point_id must be a string.")
        if not isinstance(p.get("content_text"), str):
            return _err("VALIDATION_ERROR", f"points[{i}].content_text must be a string.")
        emb = p.get("embedding")
        if not isinstance(emb, list) or len(emb) < 1:
            return _err("VALIDATION_ERROR", f"points[{i}].embedding must be a non-empty array.")
        for j, v in enumerate(emb):
            if not isinstance(v, (int, float)):
                return _err("VALIDATION_ERROR", f"points[{i}].embedding[{j}] must be a number.")
        if p.get("payload") is not None and not isinstance(p.get("payload"), dict):
            return _err("VALIDATION_ERROR", f"points[{i}].payload must be an object.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    collections = _load("vector_collections.json")
    memory_points = _load("memory_points.json")
    search_requests = _load("search_requests.json")

    # Resolve workspace + collection (must exist and be compatible)
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    col = next((c for c in collections if isinstance(c, dict) and c.get("id") == collection_id), None)

    # Create request log row in 'received' no matter what (best-effort, but must persist)
    req_row = {
        "id": _new_req_id(),
        "workspace_id": workspace_id,
        "api_key_id": None,
        "tool_name": "qdrant-store",
        "status": "received",
        "collection_id": collection_id,
        "input": {"point_count": len(points)},
        "result_count": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    if ws is None:
        _finalize(search_requests, req_row, "failed", err_code="WORKSPACE_NOT_FOUND", err_msg="workspace not found")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        _finalize(search_requests, req_row, "failed", err_code="WORKSPACE_SUSPENDED", err_msg="workspace not active; request rejected")
        return _err("UNAUTHORIZED", "Workspace not active; request rejected.", status=ws.get("status"))

    if col is None or col.get("workspace_id") != workspace_id:
        _finalize(search_requests, req_row, "failed", err_code="COLLECTION_NOT_FOUND", err_msg="collection not found for workspace")
        return _err("NOT_FOUND", "Collection not found for workspace.", collection_id=collection_id)
    if col.get("status") == "deleted":
        _finalize(search_requests, req_row, "failed", err_code="COLLECTION_DELETED", err_msg="target collection unavailable or deleted")
        return _err("UNAUTHORIZED", "Target collection unavailable or deleted.", collection_status=col.get("status"))

    # Ambient auth: pick any active API key in this workspace that has 'store' scope and is not rate-limited.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active" and isinstance(k.get("scopes"), list) and ("store" in k.get("scopes"))]
    if not active_keys:
        _finalize(search_requests, req_row, "failed", err_code="AUTH_REQUIRED", err_msg="missing api key; session not authorized for tool")
        return _err("UNAUTHORIZED", "No active API key with required scope for this workspace/tool.")

    # Rate limit check (rolling 60s) for any candidate key; select one that is within limit.
    def _parse_ts(s):
        try:
            if not isinstance(s, str) or not s.endswith("Z"):
                return None
            return datetime.datetime.fromisoformat(s[:-1])
        except Exception:
            return None

    now_ts = now_dt
    chosen_key = None
    for k in active_keys:
        rpm = k.get("rate_limit_rpm")
        if rpm is None:
            chosen_key = k
            break
        if not isinstance(rpm, int) or rpm < 1:
            continue
        window_start = now_ts - datetime.timedelta(seconds=60)
        used = 0
        for r in search_requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != k.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start and ts <= now_ts:
                used += 1
        if used < rpm:
            chosen_key = k
            break

    if chosen_key is None:
        # If all candidates are limited, mark as rate_limited.
        _finalize(search_requests, req_row, "rate_limited", err_code="RATE_LIMIT_RPM", err_msg="too many requests in 60s window")
        return _err("RATE_LIMIT", "Rate limit exceeded for API key.", rule="api_keys.rate_limit_rpm rolling 60s window")

    # attach chosen key to request log and update key last_used_at on success later
    req_row["api_key_id"] = chosen_key.get("id")
    _save("search_requests.json", search_requests)

    # Enforce embedding length == vector_size for target collection (business rule)
    vector_size = col.get("vector_size")
    if not isinstance(vector_size, int) or vector_size < 2:
        _finalize(search_requests, req_row, "failed", err_code="COLLECTION_INVALID", err_msg="collection vector_size invalid")
        return _err("CONFLICT", "Target collection configuration invalid.", vector_size=vector_size)

    for i, p in enumerate(points):
        if len(p["embedding"]) != vector_size:
            _finalize(search_requests, req_row, "failed", err_code="VECTOR_SIZE_MISMATCH", err_msg=f"embedding length {len(p['embedding'])} does not match collection vector_size {vector_size}")
            return _err(
                "VALIDATION_ERROR",
                "Embedding length must equal target collection vector_size (business rule: json_array_length(embedding) = vector_collections.vector_size).",
                expected=vector_size,
                got=len(p["embedding"]),
                index=i,
            )

    # Uniqueness constraints within collection: external_point_id unique; content_hash unique (when provided).
    # (content_hash isn't part of input schema; if present in existing rows, we must still enforce uniqueness when updating via external_point_id/id? We'll enforce only if a point row already has content_hash and update doesn't change it; callers cannot set it here.)
    existing_by_id = {}
    existing_by_external = {}
    existing_external_values = set()
    existing_content_hash_values = set()
    for mp in memory_points:
        if not isinstance(mp, dict):
            continue
        if mp.get("collection_id") != collection_id:
            continue
        pid = mp.get("id")
        if isinstance(pid, str):
            existing_by_id[pid] = mp
        ext = mp.get("external_point_id")
        if isinstance(ext, str):
            existing_by_external[ext] = mp
            existing_external_values.add(ext)
        ch = mp.get("content_hash")
        if isinstance(ch, str):
            existing_content_hash_values.add(ch)

    # Validate intra-request duplicates for external_point_id and id (avoid conflicts)
    seen_ids = set()
    seen_exts = set()
    for i, p in enumerate(points):
        if p.get("id") is not None:
            if p["id"] in seen_ids:
                _finalize(search_requests, req_row, "failed", err_code="DUPLICATE_ID", err_msg="duplicate point id in request")
                return _err("CONFLICT", "Duplicate point id in request batch.", point_id=p["id"], index=i)
            seen_ids.add(p["id"])
        if p.get("external_point_id") is not None:
            if p["external_point_id"] in seen_exts:
                _finalize(search_requests, req_row, "failed", err_code="DUPLICATE_EXTERNAL_POINT_ID", err_msg="duplicate external_point_id in request")
                return _err("CONFLICT", "Duplicate external_point_id in request batch.", external_point_id=p["external_point_id"], index=i)
            seen_exts.add(p["external_point_id"])

    # Apply upserts
    def _new_point_id():
        return "qdr_pt_" + uuid.uuid4().hex[:24]

    stored = []
    written = 0

    for i, p in enumerate(points):
        pid = p.get("id")
        ext = p.get("external_point_id")

        target = None
        # external_point_id upsert within same collection
        if isinstance(ext, str):
            target = existing_by_external.get(ext)
        # else by id if provided
        if target is None and isinstance(pid, str):
            target = existing_by_id.get(pid)

        if target is not None:
            # Reject "id changes identity" conflict: if both provided but point doesn't match
            if isinstance(pid, str) and target.get("id") != pid:
                _finalize(search_requests, req_row, "failed", err_code="ID_CONFLICT", err_msg="point id conflicts with existing external_point_id mapping")
                return _err("CONFLICT", "Provided id conflicts with existing external_point_id mapping.", index=i)
            if isinstance(ext, str) and target.get("external_point_id") not in (None, ext):
                _finalize(search_requests, req_row, "failed", err_code="EXTERNAL_ID_CONFLICT", err_msg="external_point_id conflicts with existing id mapping")
                return _err("CONFLICT", "Provided external_point_id conflicts with existing id mapping.", index=i)

            # Update allowed fields; do not resurrect tombstoned points (irreversible)
            if target.get("status") == "tombstoned":
                _finalize(search_requests, req_row, "failed", err_code="INVALID_TRANSITION", err_msg="cannot update tombstoned point")
                return _err("INVALID_TRANSITION", "Cannot update a tombstoned point (transition irreversible).", point_id=target.get("id"), index=i)

            target["embedding"] = p["embedding"]
            target["content_text"] = p.get("content_text")
            target["payload"] = p.get("payload")
            if isinstance(ext, str):
                target["external_point_id"] = ext
            target["updated_at"] = now
            written += 1
            stored.append({"id": target.get("id"), "external_point_id": target.get("external_point_id"), "status": "updated"})
            continue

        # Insert new row
        if pid is None:
            pid = _new_point_id()

        # Ensure id not already used globally (primary key)
        if pid in existing_by_id:
            _finalize(search_requests, req_row, "failed", err_code="POINT_ID_EXISTS", err_msg="point id already exists")
            return _err("CONFLICT", "Point id already exists.", point_id=pid, index=i)

        if isinstance(ext, str) and ext in existing_external_values:
            _finalize(search_requests, req_row, "failed", err_code="EXTERNAL_POINT_ID_EXISTS", err_msg="external_point_id already exists in collection")
            return _err("CONFLICT", "external_point_id already exists in this collection.", external_point_id=ext, index=i)

        new_row = {
            "id": pid,
            "workspace_id": workspace_id,
            "collection_id": collection_id,
            "external_point_id": ext,
            "status": "active",
            "content_text": p.get("content_text"),
            "embedding": p["embedding"],
            "payload": p.get("payload"),
            "content_hash": None,
            "created_by_api_key_id": chosen_key.get("id"),
            "created_at": now,
            "updated_at": now,
            "deleted_at": None,
        }
        memory_points.append(new_row)
        existing_by_id[pid] = new_row
        if isinstance(ext, str):
            existing_by_external[ext] = new_row
            existing_external_values.add(ext)
        written += 1
        stored.append({"id": pid, "external_point_id": ext, "status": "inserted"})

    if written < 1:
        _finalize(search_requests, req_row, "failed", err_code="NO_EFFECT", err_msg="no points written")
        return _err("NOT_FOUND", "No points were written.")

    # Persist mutations
    _save("memory_points.json", memory_points)
    # Update API key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == chosen_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _finalize(search_requests, req_row, "succeeded", result_count=written)

    return {
        "workspace_id": workspace_id,
        "collection_id": collection_id,
        "written": written,
        "points": stored,
        "request_id": req_row["id"],
    }

def qdrant_find(workspace_id, collection_id=None, query_text=None, query_embedding=None, top_k=None, filter=None, include_payload=None, include_embedding=None, include_content=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, re, uuid, time, math, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0013000" if __import__("os").path.isdir("./environment_mix/0013000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _new_req_id():
        return "qdr_req_" + uuid.uuid4().hex[:24]

    def _parse_ts(s):
        try:
            if not isinstance(s, str) or not s.endswith("Z"):
                return None
            return datetime.datetime.fromisoformat(s[:-1])
        except Exception:
            return None

    # Defaults
    include_payload = False if include_payload is None else include_payload
    include_embedding = False if include_embedding is None else include_embedding
    include_content = False if include_content is None else include_content

    # ---- Validate inputs ----
    if not isinstance(workspace_id, str) or not re.match(r"^qdr_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if collection_id is not None and (not isinstance(collection_id, str) or not re.match(r"^qdr_col_[A-Za-z0-9]+$", collection_id)):
        return _err("VALIDATION_ERROR", "Invalid collection_id.")
    if query_text is not None and not isinstance(query_text, str):
        return _err("VALIDATION_ERROR", "query_text must be a string.")
    if query_embedding is not None:
        if not isinstance(query_embedding, list):
            return _err("VALIDATION_ERROR", "query_embedding must be an array.")
        for j, v in enumerate(query_embedding):
            if not isinstance(v, (int, float)):
                return _err("VALIDATION_ERROR", f"query_embedding[{j}] must be a number.")
    if top_k is not None and (not isinstance(top_k, int) or top_k < 1):
        return _err("VALIDATION_ERROR", "top_k must be an integer >= 1.")
    if limit is not None and (not isinstance(limit, int) or limit < 1):
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    if filter is not None and not isinstance(filter, dict):
        return _err("VALIDATION_ERROR", "filter must be an object.")
    for nm, val in [("include_payload", include_payload), ("include_embedding", include_embedding), ("include_content", include_content)]:
        if not isinstance(val, bool):
            return _err("VALIDATION_ERROR", f"{nm} must be boolean.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if (query_text is None) == (query_embedding is None):
        return _err("VALIDATION_ERROR", "Provide exactly one of query_text or query_embedding.")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    collections = _load("vector_collections.json")
    memory_points = _load("memory_points.json")
    search_requests = _load("search_requests.json")

    # Resolve workspace
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)

    # Resolve collection: explicit or default
    resolved_collection_id = collection_id
    if resolved_collection_id is None:
        if ws and ws.get("default_collection_id"):
            resolved_collection_id = ws.get("default_collection_id")

    # Create request log row in 'received' and persist immediately
    req_row = {
        "id": _new_req_id(),
        "workspace_id": workspace_id,
        "api_key_id": None,
        "tool_name": "qdrant-find",
        "status": "received",
        "collection_id": resolved_collection_id,
        "input": {
            "query_text": query_text if query_text is not None else None,
            "has_query_embedding": query_embedding is not None,
            "top_k": top_k,
            "limit": limit,
            "filter": filter,
        },
        "result_count": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    def _finalize(status, result_count=None, err_code=None, err_msg=None):
        req_row["status"] = status
        req_row["updated_at"] = now
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        if result_count is not None:
            req_row["result_count"] = int(result_count)
        if err_code is not None:
            req_row["error_code"] = err_code
        if err_msg is not None:
            req_row["error_message"] = err_msg
        _save("search_requests.json", search_requests)

    if ws is None:
        _finalize("failed", err_code="WORKSPACE_NOT_FOUND", err_msg="workspace not found")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        _finalize("failed", err_code="WORKSPACE_SUSPENDED", err_msg="workspace not active; request rejected")
        return _err("UNAUTHORIZED", "Workspace not active; request rejected.", status=ws.get("status"))

    if resolved_collection_id is None:
        _finalize("failed", err_code="COLLECTION_REQUIRED", err_msg="no collection specified and no workspace default_collection_id set")
        return _err("VALIDATION_ERROR", "No collection_id provided and workspace has no default_collection_id.")
    if not isinstance(resolved_collection_id, str) or not re.match(r"^qdr_col_[A-Za-z0-9]+$", resolved_collection_id):
        _finalize("failed", err_code="COLLECTION_ID_INVALID", err_msg="invalid collection id")
        return _err("VALIDATION_ERROR", "Invalid collection_id.")

    col = next((c for c in collections if isinstance(c, dict) and c.get("id") == resolved_collection_id), None)
    if col is None or col.get("workspace_id") != workspace_id:
        _finalize("failed", err_code="COLLECTION_NOT_FOUND", err_msg="collection not found for workspace")
        return _err("NOT_FOUND", "Collection not found for workspace.", collection_id=resolved_collection_id)
    if col.get("status") == "deleted":
        _finalize("failed", err_code="COLLECTION_DELETED", err_msg="target collection unavailable or deleted")
        return _err("UNAUTHORIZED", "Target collection unavailable or deleted.", collection_status=col.get("status"))

    # Ambient auth: pick any active API key with 'find' scope in this workspace and not rate-limited.
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active" and isinstance(k.get("scopes"), list) and ("find" in k.get("scopes"))]
    if not active_keys:
        _finalize("failed", err_code="AUTH_REQUIRED", err_msg="missing api key; session not authorized for tool")
        return _err("UNAUTHORIZED", "No active API key with required scope for this workspace/tool.")

    chosen_key = None
    for k in active_keys:
        rpm = k.get("rate_limit_rpm")
        if rpm is None:
            chosen_key = k
            break
        if not isinstance(rpm, int) or rpm < 1:
            continue
        window_start = now_dt - datetime.timedelta(seconds=60)
        used = 0
        for r in search_requests:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != k.get("id"):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if ts >= window_start and ts <= now_dt:
                used += 1
        if used < rpm:
            chosen_key = k
            break

    if chosen_key is None:
        _finalize("rate_limited", err_code="RATE_LIMIT_RPM", err_msg="too many requests in 60s window")
        return _err("RATE_LIMIT", "Rate limit exceeded for API key.", rule="api_keys.rate_limit_rpm rolling 60s window")

    req_row["api_key_id"] = chosen_key.get("id")
    req_row["collection_id"] = resolved_collection_id
    _save("search_requests.json", search_requests)

    # Validate query embedding length if provided
    vector_size = col.get("vector_size")
    if query_embedding is not None:
        if not isinstance(vector_size, int) or vector_size < 2:
            _finalize("failed", err_code="COLLECTION_INVALID", err_msg="collection vector_size invalid")
            return _err("CONFLICT", "Target collection configuration invalid.", vector_size=vector_size)
        if len(query_embedding) != vector_size:
            _finalize("failed", err_code="VECTOR_SIZE_MISMATCH", err_msg=f"query embedding length {len(query_embedding)} does not match collection vector_size {vector_size}")
            return _err("VALIDATION_ERROR", "query_embedding length must match collection vector_size.", expected=vector_size, got=len(query_embedding))

    # If query_text is provided, this offline implementation cannot embed; use naive lexical scoring.
    # This is still "real" in the sense it searches and returns deterministic results from the store.
    q_tokens = None
    if query_text is not None:
        q_tokens = [t for t in re.split(r"[^A-Za-z0-9]+", query_text.lower()) if t]

    def _payload_matches(payload, flt):
        if flt is None:
            return True
        if not isinstance(payload, dict):
            return False
        for k, v in flt.items():
            if k not in payload:
                return False
            pv = payload.get(k)
            if isinstance(v, dict):
                if "$eq" in v:
                    if pv != v["$eq"]:
                        return False
                elif "$in" in v and isinstance(v["$in"], list):
                    if pv not in v["$in"]:
                        return False
                else:
                    return False
            else:
                if pv != v:
                    return False
        return True

    # Collect candidates: active points only, in resolved collection, workspace match
    candidates = []
    for mp in memory_points:
        if not isinstance(mp, dict):
            continue
        if mp.get("workspace_id") != workspace_id:
            continue
        if mp.get("collection_id") != resolved_collection_id:
            continue
        if mp.get("status") != "active":
            continue
        if not _payload_matches(mp.get("payload"), filter):
            continue

        score = 0.0
        if query_embedding is not None:
            emb = mp.get("embedding")
            if not isinstance(emb, list) or len(emb) != len(query_embedding):
                continue
            # cosine similarity (with safe zero norms)
            dot = 0.0
            na = 0.0
            nb = 0.0
            for a, b in zip(query_embedding, emb):
                if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
                    dot = None
                    break
                dot += float(a) * float(b)
                na += float(a) * float(a)
                nb += float(b) * float(b)
            if dot is None:
                continue
            denom = math.sqrt(na) * math.sqrt(nb)
            score = (dot / denom) if denom > 0 else 0.0
        else:
            text = mp.get("content_text") or ""
            t_tokens = [t for t in re.split(r"[^A-Za-z0-9]+", str(text).lower()) if t]
            if not t_tokens or not q_tokens:
                score = 0.0
            else:
                # simple overlap
                s = 0
                tset = set(t_tokens)
                for qt in set(q_tokens):
                    if qt in tset:
                        s += 1
                score = float(s)

        candidates.append((score, mp))

    # Sort by descending score, tie-break by updated_at desc then id
    def _ts_key(s):
        ts = _parse_ts(s)
        return ts if ts is not None else datetime.datetime(1970, 1, 1)

    candidates.sort(key=lambda x: (x[0], _ts_key(x[1].get("updated_at")), x[1].get("id") or ""), reverse=True)

    # Pagination
    k = top_k if top_k is not None else col.get("default_top_k")
    if not isinstance(k, int) or k < 1:
        k = 10
    if limit is not None:
        k = min(k, limit)

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
        except Exception:
            _finalize("failed", err_code="CURSOR_INVALID", err_msg="invalid cursor")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    total = len(candidates)
    page = candidates[offset:offset + k]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8") if has_more else None

    results = []
    for score, mp in page:
        item = {
            "id": mp.get("id"),
            "external_point_id": mp.get("external_point_id"),
            "score": score,
            "payload": mp.get("payload") if include_payload else None,
            "embedding": mp.get("embedding") if include_embedding else None,
            "content_text": mp.get("content_text") if include_content else None,
            "created_at": mp.get("created_at"),
            "updated_at": mp.get("updated_at"),
        }
        results.append(item)

    # Update key last_used_at and request log
    for krow in api_keys:
        if isinstance(krow, dict) and krow.get("id") == chosen_key.get("id"):
            krow["last_used_at"] = now
            krow["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _finalize("succeeded", result_count=len(results))

    return {
        "workspace_id": workspace_id,
        "collection_id": resolved_collection_id,
        "results": results,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "request_id": req_row["id"],
    }

def qdrant_list_collections(workspace_id, status=None, name_prefix=None, cursor=None, limit=None, **_extra):
    import json, os, datetime, time, re, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0013000" if __import__("os").path.isdir("./environment_mix/0013000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    collections = _load("vector_collections.json")
    search_requests = _load("search_requests.json")

    def _new_req_id():
        return "qdr_req_" + uuid.uuid4().hex[:24]

    def _resolve_api_key_for_workspace(ws_id):
        cands = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"]
        # admin scope preferred, else any active key
        for k in cands:
            scopes = k.get("scopes")
            if isinstance(scopes, list) and "admin" in scopes:
                return k
        return cands[0] if cands else None

    # Log as a request row too (tool_name enum excludes this in schema; keep consistent by not logging there)
    # Since schema enum only allows qdrant-store/qdrant-find, we cannot append; enforce no logging collection exists for this tool.
    # Therefore we implement without search_requests logging.

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^qdr_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if status is not None:
        if status not in ("active", "rebuilding", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status.")
    if name_prefix is not None and not isinstance(name_prefix, str):
        return _err("VALIDATION_ERROR", "name_prefix must be a string.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if limit is not None:
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active or does not exist.")

    key = _resolve_api_key_for_workspace(workspace_id)
    if key is None:
        return _err("UNAUTHORIZED", "No active API key available for this workspace.")
    scopes = key.get("scopes")
    if not (isinstance(scopes, list) and ("admin" in scopes or "find" in scopes or "store" in scopes)):
        return _err("UNAUTHORIZED", "API key lacks required scope.")

    # Pagination
    off = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("off:"):
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            off = int(s.split(":", 1)[1])
            if off < 0:
                raise ValueError()
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.")
    eff_limit = limit if limit is not None else 50

    rows = []
    for c in collections:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") != workspace_id:
            continue
        if status is not None and c.get("status") != status:
            continue
        if name_prefix is not None:
            nm = c.get("name")
            if not isinstance(nm, str) or not nm.startswith(name_prefix):
                continue
        rows.append(c)

    rows.sort(key=lambda r: (r.get("name") or "", r.get("id") or ""))

    total = len(rows)
    page = rows[off: off + eff_limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=") if has_more else None

    summaries = []
    for c in page:
        summaries.append({
            "id": c.get("id"),
            "workspace_id": c.get("workspace_id"),
            "name": c.get("name"),
            "status": c.get("status"),
            "vector_size": c.get("vector_size"),
            "distance": c.get("distance"),
            "default_top_k": c.get("default_top_k"),
            "created_at": c.get("created_at"),
            "updated_at": c.get("updated_at"),
        })

    # Update key last_used_at (best-effort)
    key["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    key["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("api_keys.json", api_keys)

    return {
        "workspace_id": workspace_id,
        "collections": summaries,
        "page": {
            "total": total,
            "count": len(summaries),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
        }
    }

