def qdrant_create_collection(workspace_id, name, vector_size, distance, default_top_k=None, payload_schema=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0013000" if __import__("os").path.isdir("./environment_mix/0013000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^qdr_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(name, str) or not (1 <= len(name) <= 128):
        return _err("VALIDATION_ERROR", "Invalid name.")
    if not isinstance(vector_size, int):
        return _err("VALIDATION_ERROR", "vector_size must be an integer.")
    # Tool schema says minimum 1, but collection constraint requires >=2.
    if vector_size < 2 or vector_size > 65536:
        return _err("VALIDATION_ERROR", "vector_size must be between 2 and 65536.")
    if distance not in ("cosine", "dot", "euclid"):
        return _err("VALIDATION_ERROR", "Invalid distance.")
    if default_top_k is None:
        default_top_k = 10
    if not isinstance(default_top_k, int) or not (1 <= default_top_k <= 1000):
        return _err("VALIDATION_ERROR", "default_top_k must be an integer between 1 and 1000.")
    if payload_schema is not None and not isinstance(payload_schema, dict):
        return _err("VALIDATION_ERROR", "payload_schema must be an object when provided.")

    workspaces = _load("workspaces.json")
    collections = _load("vector_collections.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    # Enforce unique collection name per workspace (case-sensitive, as typical DB constraint)
    for c in collections:
        if c.get("workspace_id") == workspace_id and c.get("name") == name and c.get("status") != "deleted":
            return _err("CONFLICT", "A collection with this name already exists in the workspace.")

    # Create new collection
    # Generate id with required convention
    new_id = "qdr_col_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:18]
    while any(c.get("id") == new_id for c in collections):
        new_id = "qdr_col_" + secrets.token_urlsafe(12).replace("-", "").replace("_", "")[:18]

    rec = {
        "id": new_id,
        "workspace_id": workspace_id,
        "name": name,
        "status": "active",
        "vector_size": vector_size,
        "distance": distance,
        "default_top_k": default_top_k,
        "payload_schema": payload_schema,
        "created_at": now,
        "updated_at": now,
    }
    collections.append(rec)
    _save("vector_collections.json", collections)

    # Validate workspace.default_collection_id rule (if set) references non-deleted collection in same workspace.
    # (Do not auto-mutate; just ensure datastore stays consistent where possible.)
    if ws.get("default_collection_id"):
        dcid = ws.get("default_collection_id")
        dc = next((c for c in collections if c.get("id") == dcid), None)
        if not dc or dc.get("workspace_id") != workspace_id or dc.get("status") == "deleted":
            # Workspace is inconsistent; surface as validation error rather than hiding it.
            return _err("VALIDATION_ERROR", "Workspace default_collection_id is invalid or references a deleted collection.")

    return {
        "collection": rec
    }

def qdrant_update_collection(workspace_id, collection_id, name=None, default_top_k=None, payload_schema=None, status=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0013000" if __import__("os").path.isdir("./environment_mix/0013000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate required identifiers
    if not isinstance(workspace_id, str) or not re.match(r"^qdr_ws_[A-Za-z0-9]+$", workspace_id):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")
    if not isinstance(collection_id, str) or not re.match(r"^qdr_col_[A-Za-z0-9]+$", collection_id):
        return _err("VALIDATION_ERROR", "Invalid collection_id.")

    # Validate optionals
    if name is not None:
        if not isinstance(name, str) or not (1 <= len(name) <= 128):
            return _err("VALIDATION_ERROR", "Invalid name.")
    if default_top_k is not None:
        if not isinstance(default_top_k, int) or not (1 <= default_top_k <= 1000):
            return _err("VALIDATION_ERROR", "default_top_k must be an integer between 1 and 1000.")
    if payload_schema is not None and not isinstance(payload_schema, dict):
        return _err("VALIDATION_ERROR", "payload_schema must be an object when provided.")
    if status is not None and status not in ("active", "rebuilding", "deleted"):
        return _err("VALIDATION_ERROR", "Invalid status.")

    workspaces = _load("workspaces.json")
    collections = _load("vector_collections.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active.")

    col = next((c for c in collections if c.get("id") == collection_id and c.get("workspace_id") == workspace_id), None)
    if not col:
        return _err("NOT_FOUND", "Collection not found in workspace.")

    # Cannot modify deleted collection (explicit rule)
    if col.get("status") == "deleted":
        return _err("VALIDATION_ERROR", "Cannot modify a deleted collection.")

    # Name uniqueness per workspace if changing
    if name is not None and name != col.get("name"):
        for c in collections:
            if c.get("workspace_id") == workspace_id and c.get("name") == name and c.get("id") != collection_id and c.get("status") != "deleted":
                return _err("CONFLICT", "A collection with this name already exists in the workspace.")
        col["name"] = name

    # Apply mutable fields
    if default_top_k is not None:
        col["default_top_k"] = default_top_k
    if payload_schema is not None:
        col["payload_schema"] = payload_schema

    # Status transition enforcement
    if status is not None and status != col.get("status"):
        allowed = {
            "active": ["rebuilding", "deleted"],
            "rebuilding": ["active", "deleted"],
            "deleted": [],
        }
        cur = col.get("status")
        if cur not in allowed:
            return _err("VALIDATION_ERROR", "Collection has an unknown current status.")
        if status not in allowed[cur]:
            return _err("INVALID_TRANSITION", f"Illegal status transition from '{cur}' to '{status}'.")
        col["status"] = status

    # If nothing changed, treat as not found? (Mutation matched a row but no changes requested)
    # Real APIs typically succeed idempotently; however requirement says "NO SUCCESS WITHOUT EFFECT" for mutations
    # that matched no row. Here we matched a row; if caller sent no fields, it's a validation error.
    if name is None and default_top_k is None and payload_schema is None and status is None:
        return _err("VALIDATION_ERROR", "No updatable fields provided.")

    col["updated_at"] = now
    _save("vector_collections.json", collections)

    # Validate workspace.default_collection_id rule (if set) references non-deleted collection in same workspace.
    if ws.get("default_collection_id"):
        dcid = ws.get("default_collection_id")
        dc = next((c for c in collections if c.get("id") == dcid), None)
        if not dc or dc.get("workspace_id") != workspace_id or dc.get("status") == "deleted":
            return _err("VALIDATION_ERROR", "Workspace default_collection_id is invalid or references a deleted collection.")

    return {
        "collection": col
    }

