        "result_count": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }
    search_requests.append(req_row)
    _save("search_requests.json", search_requests)

    def _finalize(status, result_count=None, err_code=None, err_msg=None):
        req_row["status"] = status
        req_row["updated_at"] = now
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        if result_count is not None:
            req_row["result_count"] = int(result_count)
        if err_code is not None:
            req_row["error_code"] = err_code
        if err_msg is not None:
            req_row["error_message"] = err_msg
        _save("search_requests.json", search_requests)

    if ws is None:
        _finalize("failed", err_code="WORKSPACE_NOT_FOUND", err_msg="workspace not found")
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)
    if ws.get("status") != "active":
        _finalize("failed", err_code="WORKSPACE_SUSPENDED", err_msg="workspace not active; request rejected")
        return _err("UNAUTHORIZED", "Workspace not active; request rejected.", status=ws.get("status"))

    if col is None or col.get("workspace_id") != workspace_id:
        _finalize("failed", err_code="COLLECTION_NOT_FOUND", err_msg="collection not found for workspace")
        return _err("NOT_FOUND", "Collection not found for workspace.", collection_id=collection_id)
    if col.get("status") == "deleted":
        _finalize("failed", err_code="COLLECTION_DELETED", err_msg="target collection unavailable or deleted")
        return _err("UNAUTHORIZED", "Target collection unavailable or deleted.", collection_status=col.get("status"))

    # Ambient auth: require any active key with 'find' scope to read
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active" and isinstance(k.get("scopes"), list) and ("find" in k.get("scopes"))]
    if not active_keys:
        _finalize("failed", err_code="AUTH_REQUIRED", err_msg="missing api key; session not authorized for tool")
        return _err("UNAUTHORIZED", "No active API key with required scope for this workspace/tool.")

    chosen_key = active_keys[0]
    req_row["api_key_id"] = chosen_key.get("id")
    _save("search_requests.json", search_requests)

    mp = next((p for p in memory_points if isinstance(p, dict) and p.get("id") == point_id and p.get("workspace_id") == workspace_id and p.get("collection_id") == collection_id), None)
    if mp is None:
        _finalize("failed", err_code="POINT_NOT_FOUND", err_msg="point not found")
        return _err("NOT_FOUND", "Memory point not found.", point_id=point_id)

    if mp.get("status") == "tombstoned" and not include_deleted:
        _finalize("failed", err_code="POINT_TOMBSTONED", err_msg="point is deleted")
        return _err("NOT_FOUND", "Memory point not found.", point_id=point_id)

    # update key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == chosen_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _finalize("succeeded", result_count=1)

    out = {
        "workspace_id": workspace_id,
        "collection_id": collection_id,
        "point": {
            "id": mp.get("id"),
            "external_point_id": mp.get("external_point_id"),
            "status": mp.get("status"),
            "payload": mp.get("payload") if include_payload else None,
            "embedding": mp.get("embedding") if include_embedding else None,
            "content_text": mp.get("content_text") if include_content else None,
            "created_at": mp.get("created_at"),
            "updated_at": mp.get("updated_at"),
            "deleted_at": mp.get("deleted_at") if include_deleted else None,
        },
        "request_id": req_row["id"],
    }
    return out
